package com.crms.entity;import jakarta.persistence.*;import java.time.LocalDate;@Entity public class PlacementDrive{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String name;private String description;private LocalDate startDate,endDate;private boolean active=true;public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public LocalDate getStartDate(){return startDate;}public void setStartDate(LocalDate v){startDate=v;}public LocalDate getEndDate(){return endDate;}public void setEndDate(LocalDate v){endDate=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}
